def normalize_body(body: str) -> str:
    body = unicodedata.normalize("NFC", body.replace("\r\n", "\n").replace("\r", "\n"))
    lines = [line.rstrip() for line in body.split("\n")]
    while lines and not lines[0]: lines.pop(0)
    while lines and not lines[-1]: lines.pop()
    return "\n".join(lines)


def rp(row, cfg, review_body):
    def cm(v): return ";".join(sorted(x.strip() for x in v.split(";") if x.strip() and x.strip() != "—"))
    reviewed = f"SRC-ARXIV@arXiv:{row['arxiv_id']}v1"
    claim = f"claim:{cfg['f']}"
    review = f"review:{cfg['f']}"
    parts = ["review-completion-v1", cfg["f"], f"paper-v1:{row['arxiv_id']}", f"arXiv:{row['arxiv_id']}v1", "SRC-ARXIV", f"arXiv:{row['arxiv_id']}v1", reviewed, "deep", "review-override:knowledge_gap", cm(cfg["method"]), cm(cfg["eval"]), cm(cfg["limits"]), cm(cfg["artifact"]), claim, review, "review-body-sha256:" + hashlib.sha256(normalize_body(review_body).encode()).hexdigest()]
    return "RP-" + hashlib.sha256("|".join(parts).encode()).hexdigest()[:16]


